#include <stdio.h>
#include "lin_master.h"
int main(void){lin_master_t m;lin_master_init(&m,2000);lin_master_add_slave(&m,(lin_slave_t){.node_id=0x10,.kind=LIN_SLAVE_BODY,.present=true,.response_delay_us=500,.value=123});lin_master_add_slave(&m,(lin_slave_t){.node_id=0x11,.kind=LIN_SLAVE_THERMAL,.present=true,.response_delay_us=700,.value=42});lin_master_add_slave(&m,(lin_slave_t){.node_id=0x12,.kind=LIN_SLAVE_DOOR,.present=false,.response_delay_us=900,.value=1});lin_master_add_slot(&m,(lin_schedule_slot_t){0x10,LIN_SLOT_UNCONDITIONAL,10,3,0});lin_master_add_slot(&m,(lin_schedule_slot_t){0x11,LIN_SLOT_UNCONDITIONAL,10,3,1});lin_master_add_slot(&m,(lin_schedule_slot_t){0x12,LIN_SLOT_UNCONDITIONAL,10,3,2});lin_master_add_slot(&m,(lin_schedule_slot_t){0x3C,LIN_SLOT_DIAGNOSTIC,20,8,0});for(int i=0;i<8;i++){lin_frame_t tx={0},rx={0};bool got=false;lin_status_t s=lin_master_tick(&m,&tx,&rx,&got);printf("slot=%u id=0x%02X result=%d received=%d\n",m.schedule.index,tx.id,s,got);}printf("tx=%u rx=%u timeout=%u recovered=%u diag=%u\n",m.stats.frames_sent,m.stats.frames_received,m.stats.timeouts,m.stats.recovered_slots,m.stats.diagnostic_requests);return 0;}
